// scratch probe helper: runs the reference binary on inline strings
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test14_executable';
const show = (s) => JSON.stringify(s);
const probes = [
  ['plain accented', 'café'],
  ['cjk', '日本語'],
  ['cyrillic', 'Привет'],
  ['greek', 'αβγ'],
  ['emoji astral', '😀'],
  ['nbsp only', ' '],
  ['nbsp inside', 'a b'],
  ['bom start', '﻿hello'],
  ['bom mid', 'a﻿b'],
  ['NEL bare', 'ab'],
  ['LS bare', 'a b'],
  ['PS bare', 'a b'],
  ['NEL in dq', '"ab"'],
  ['LS in dq', '"a b"'],
  ['spaces only', '   '],
  ['quoted spaces', '"   "'],
  ['lead/trail sp quoted', '" a "'],
  ['sp then break', '"a \\nb"'],
  ['break then sp', '"a\\n b"'],
  ['key unicode', 'café: b'],
  ['map unicode val', 'k: 日本'],
  ['literal block unicode', 'k: |\n  café'],
  ['nbsp as indent', 'k:\n  v'],
];
for (const [name, s] of probes) {
  let out, rc = 0;
  try {
    out = execFileSync(EXE, ['--a', s], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    rc = e.status; out = (e.stdout || '') + (e.stderr || '');
    const lines = out.trim().split('\n');
    out = lines.filter(l => /Error|error/.test(l)).slice(0, 2).join(' | ');
  }
  console.log('###', name, show(s), '=> rc=' + rc);
  console.log('   ', show(out));
}

