const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0, err = 0;
const seen = new Map();
for (const f of files) {
  const s = readFileSync(DIR + '/' + f, 'utf8');
  if (seen.has(s)) console.log('!! DUPLICATE', f, 'same as', seen.get(s));
  seen.set(s, f);
  try {
    execFileSync(EXE, ['--a', s], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
